import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync, readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';

const databasePath = process.env.DB_PATH || './data/workboard.sqlite';
if (databasePath !== ':memory:') mkdirSync(dirname(resolve(databasePath)), { recursive: true });
const db = new DatabaseSync(databasePath);
db.exec(`
  CREATE TABLE IF NOT EXISTS projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL
  );
  CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL REFERENCES projects(id),
    title TEXT NOT NULL,
    completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1))
  );
`);
db.exec('PRAGMA foreign_keys = ON');
const listProjects = db.prepare('SELECT id, name FROM projects ORDER BY id');
const getProject = db.prepare('SELECT id, name FROM projects WHERE id = ?');
const createProject = db.prepare('INSERT INTO projects (name) VALUES (?)');
const listTasks = db.prepare('SELECT id, project_id, title, completed FROM tasks WHERE project_id = ? ORDER BY id');
const getTask = db.prepare('SELECT id, project_id, title, completed FROM tasks WHERE project_id = ? AND id = ?');
const createTask = db.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)');
const updateTask = db.prepare('UPDATE tasks SET completed = ? WHERE project_id = ? AND id = ?');
const taskJson = (task) => ({ ...task, completed: Boolean(task.completed) });
const assets = new Map([
  ['/', ['text/html; charset=utf-8', readFileSync(new URL('./public/index.html', import.meta.url))]],
  ['/app.js', ['text/javascript; charset=utf-8', readFileSync(new URL('./public/app.js', import.meta.url))]],
  ['/style.css', ['text/css; charset=utf-8', readFileSync(new URL('./public/style.css', import.meta.url))]],
]);

function json(res, status, body) {
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' });
  res.end(JSON.stringify(body));
}

async function readInput(req, res) {
  let body = '';
  for await (const chunk of req) {
    body += chunk;
    if (Buffer.byteLength(body) > 65536) {
      json(res, 413, { error: 'Request too large' });
      return;
    }
  }
  try { return JSON.parse(body); } catch { json(res, 400, { error: 'Invalid JSON' }); }
}

const server = http.createServer(async (req, res) => {
  try {
    const pathname = new URL(req.url, 'http://localhost').pathname;
    if (req.method === 'GET' && pathname === '/health') return json(res, 200, { status: 'ok' });
    if (req.method === 'GET' && pathname === '/api/projects') return json(res, 200, listProjects.all());
    const projectMatch = pathname.match(/^\/api\/projects\/(\d+)$/);
    if (req.method === 'GET' && projectMatch) {
      const project = getProject.get(projectMatch[1]);
      return json(res, project ? 200 : 404, project || { error: 'Project not found' });
    }
    if (req.method === 'POST' && pathname === '/api/projects') {
      const input = await readInput(req, res);
      if (res.writableEnded) return;
      const name = typeof input?.name === 'string' ? input.name.trim() : '';
      if (!name) return json(res, 400, { error: 'Project name is required' });
      const result = createProject.run(name);
      return json(res, 201, getProject.get(result.lastInsertRowid));
    }
    const tasksMatch = pathname.match(/^\/api\/projects\/(\d+)\/tasks$/);
    if (tasksMatch && ['GET', 'POST'].includes(req.method)) {
      const projectId = tasksMatch[1];
      if (!getProject.get(projectId)) return json(res, 404, { error: 'Project not found' });
      if (req.method === 'GET') return json(res, 200, listTasks.all(projectId).map(taskJson));
      const input = await readInput(req, res);
      if (res.writableEnded) return;
      const title = typeof input?.title === 'string' ? input.title.trim() : '';
      if (!title) return json(res, 400, { error: 'Task title is required' });
      const result = createTask.run(projectId, title);
      return json(res, 201, taskJson(getTask.get(projectId, result.lastInsertRowid)));
    }
    const taskMatch = pathname.match(/^\/api\/projects\/(\d+)\/tasks\/(\d+)$/);
    if (req.method === 'PATCH' && taskMatch) {
      const [, projectId, taskId] = taskMatch;
      if (!getTask.get(projectId, taskId)) return json(res, 404, { error: 'Task not found' });
      const input = await readInput(req, res);
      if (res.writableEnded) return;
      if (typeof input?.completed !== 'boolean') return json(res, 400, { error: 'Completion must be a boolean' });
      updateTask.run(Number(input.completed), projectId, taskId);
      return json(res, 200, taskJson(getTask.get(projectId, taskId)));
    }
    if (req.method === 'GET') {
      const asset = assets.get(/^\/projects\/\d+$/.test(pathname) ? '/' : pathname);
      if (asset) {
        res.writeHead(200, { 'Content-Type': asset[0], 'Cache-Control': 'no-cache' });
        return res.end(asset[1]);
      }
    }
    json(res, 404, { error: 'Not found' });
  } catch (error) {
    console.error(error);
    if (!res.headersSent) json(res, 500, { error: 'Unable to complete request' });
    else res.end();
  }
});

server.listen(Number(process.env.PORT || 8080), '0.0.0.0', () => {
  console.log(`Workboard listening on port ${server.address().port}`);
});
for (const signal of ['SIGINT', 'SIGTERM']) {
  process.on(signal, () => server.close(() => { db.close(); process.exit(0); }));
}
const app = document.querySelector('#app');

async function request(path, options) {
  const response = await fetch(path, options);
  const data = await response.json();
  if (!response.ok) throw new Error(data.error || 'Unable to complete request');
  return data;
}

function showError(message) {
  let alert = app.querySelector('[role="alert"]');
  if (!alert) {
    alert = document.createElement('p');
    alert.setAttribute('role', 'alert');
    app.append(alert);
  }
  alert.textContent = message;
}

async function renderProjects() {
  document.title = 'Workboard';
  app.innerHTML = `
    <h1>Workboard</h1>
    <form>
      <label for="project-name">Project name</label>
      <div class="create-controls">
        <input id="project-name" name="name" type="text" autocomplete="off">
        <button type="submit" disabled>Create project</button>
      </div>
    </form>
    <p role="alert" hidden></p>
    <div id="projects"></div>
  `;
  const form = app.querySelector('form');
  const input = app.querySelector('input');
  const alert = app.querySelector('[role="alert"]');
  const list = app.querySelector('#projects');
  function appendProject(project) {
    const row = document.createElement('div');
    row.dataset.testid = 'project-row';
    row.className = 'project-row';
    const name = document.createElement('span');
    name.textContent = project.name;
    const button = document.createElement('button');
    button.type = 'button';
    button.textContent = 'Open project';
    button.addEventListener('click', () => { window.location.href = `/projects/${project.id}`; });
    row.append(name, button);
    list.append(row);
  }
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    alert.hidden = true;
    const name = input.value.trim();
    if (!name) {
      alert.textContent = 'Project name is required';
      alert.hidden = false;
      return;
    }
    const button = form.querySelector('button');
    button.disabled = true;
    try {
      const project = await request('/api/projects', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name }),
      });
      appendProject(project);
      input.value = '';
      input.focus();
    } catch (error) {
      alert.textContent = error.message;
      alert.hidden = false;
    } finally {
      button.disabled = false;
    }
  });
  try {
    const projects = await request('/api/projects');
    projects.forEach(appendProject);
  } catch (error) {
    alert.textContent = error.message;
    alert.hidden = false;
  } finally {
    form.querySelector('button').disabled = false;
  }
}

async function renderProject(id) {
  app.innerHTML = '<button type="button">Projects</button><h1>Loading project…</h1>';
  app.querySelector('button').addEventListener('click', () => { window.location.href = '/'; });
  try {
    const project = await request(`/api/projects/${id}`);
    app.querySelector('h1').textContent = project.name;
    document.title = `${project.name} · Workboard`;
    renderTasks(id);
  } catch (error) {
    app.querySelector('h1').textContent = 'Project unavailable';
    showError(error.message);
  }
}

async function renderTasks(projectId) {
  const section = document.createElement('section');
  section.innerHTML = `
    <form>
      <label for="task-title">Task title</label>
      <div class="create-controls">
        <input id="task-title" name="title" type="text" autocomplete="off">
        <button type="submit" disabled>Create task</button>
      </div>
    </form>
    <p role="alert" hidden></p>
    <div class="task-filter">
      <label for="task-filter">Task filter</label>
      <select id="task-filter">
        <option value="all" selected>All</option>
        <option value="open">Open</option>
        <option value="completed">Completed</option>
      </select>
    </div>
    <div id="tasks"></div>
  `;
  app.append(section);
  const form = section.querySelector('form');
  const input = section.querySelector('input');
  const button = form.querySelector('button');
  const alert = section.querySelector('[role="alert"]');
  const filter = section.querySelector('select');
  const list = section.querySelector('#tasks');
  const endpoint = `/api/projects/${projectId}/tasks`;
  let tasks = [];
  const pending = new Set();

  function displayError(error) {
    alert.textContent = error.message;
    alert.hidden = false;
  }

  function renderRows() {
    list.replaceChildren();
    for (const task of tasks) {
      if (filter.value === 'open' && task.completed) continue;
      if (filter.value === 'completed' && !task.completed) continue;
      const row = document.createElement('div');
      row.dataset.testid = 'task-row';
      row.className = 'task-row';
      const title = document.createElement('span');
      title.textContent = task.title;
      const checkbox = document.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.setAttribute('aria-label', `Complete ${task.title}`);
      checkbox.checked = task.completed;
      checkbox.disabled = pending.has(task.id);
      checkbox.addEventListener('change', async () => {
        alert.hidden = true;
        pending.add(task.id);
        checkbox.disabled = true;
        try {
          const saved = await request(`${endpoint}/${task.id}`, {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ completed: checkbox.checked }),
          });
          task.completed = saved.completed;
        } catch (error) {
          displayError(error);
        } finally {
          pending.delete(task.id);
          renderRows();
        }
      });
      row.append(title, checkbox);
      list.append(row);
    }
  }

  filter.addEventListener('change', renderRows);
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    alert.hidden = true;
    const title = input.value.trim();
    if (!title) return displayError(new Error('Task title is required'));
    button.disabled = true;
    try {
      const task = await request(endpoint, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title }),
      });
      tasks.push(task);
      renderRows();
      input.value = '';
      input.focus();
    } catch (error) {
      displayError(error);
    } finally {
      button.disabled = false;
    }
  });
  try {
    tasks = await request(endpoint);
    renderRows();
    button.disabled = false;
  } catch (error) {
    displayError(error);
  }
}

